class HabitApp extends StatelessWidget {
  const HabitApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner: false, title: 'Habit Tracker', theme: ThemeData(useMaterial3: true, scaffoldBackgroundColor: AppColors.bg, colorScheme: ColorScheme.fromSeed(seedColor: AppColors.blue)), home: const HomeShell());
}

class HomeShell extends StatefulWidget {
  const HomeShell({super.key});
  @override State<HomeShell> createState() => _HomeShellState();
}

class _HomeShellState extends State<HomeShell> {
  final store = StorageService();
  List<Habit> habits = [];
  List<Map<String, dynamic>> todos = [];
  Map<String, int> moods = {};
  Map<String, int> timers = {};
  DateTime selected = DateTime.now();
  String? pin;
  int tab = 0;
  bool loading = true;
  bool locked = false;
  @override void initState() { super.initState(); load(); }
  Future<void> load() async { habits = await store.loadHabits(); todos = await store.loadTodos(); moods = await store.loadMoods(); timers = await store.loadTimerSeconds(); pin = await store.loadPin(); locked = pin != null && pin!.isNotEmpty; if (mounted) setState(() => loading = false); }
  Future<void> saveHabits() => store.saveHabits(habits);
  Future<void> addHabit() async { final form = await showModalBottomSheet<HabitForm>(context: context, isScrollControlled: true, builder: (_) => const HabitEditor()); if (form == null || form.name.trim().isEmpty) return; habits.add(form.makeHabit()); setState(() {}); await saveHabits(); }
  Future<void> editHabit(Habit h) async { final form = await showModalBottomSheet<HabitForm>(context: context, isScrollControlled: true, builder: (_) => HabitEditor(habit: h)); if (form == null) return; if (form.delete) { habits.removeWhere((x) => x.id == h.id); } else { h.name = form.name; h.category = form.category; h.goal = form.goal; h.unit = form.unit; h.frequency = form.frequency; h.weekdays = form.weekdays; h.tags = form.tags; h.notes = form.notes; h.pinned = form.pinned; h.active = form.active; } setState(() {}); await saveHabits(); }
  Future<void> toggleHabit(Habit h, DateTime d) async { h.setDone(d, !h.isDone(d)); setState(() {}); await saveHabits(); }
  Future<void> openHabit(Habit h) async { await Navigator.push(context, MaterialPageRoute(builder: (_) => HabitDetail(habit: h, onSave: saveHabits))); if (mounted) setState(() {}); }
  Future<void> addTodo() async { final form = await showDialog<TodoForm>(context: context, builder: (_) => const TodoEditor()); if (form == null || form.title.trim().isEmpty) return; todos.add({'id': DateTime.now().microsecondsSinceEpoch.toString(), 'title': form.title.trim(), 'category': form.category, 'priority': form.priority, 'done': false}); setState(() {}); await store.saveTodos(todos); }
  Future<void> editTodo(int index) async { final form = await showDialog<TodoForm>(context: context, builder: (_) => TodoEditor(existing: todos[index])); if (form == null) return; todos[index]['title'] = form.title.trim(); todos[index]['category'] = form.category; todos[index]['priority'] = form.priority; setState(() {}); await store.saveTodos(todos); }
  Future<void> toggleTodo(int index) async { todos[index]['done'] = todos[index]['done'] != true; setState(() {}); await store.saveTodos(todos); }
  Future<void> deleteTodo(int index) async { todos.removeAt(index); setState(() {}); await store.saveTodos(todos); }
  Future<void> setMood(int value) async { moods[Habit.key(selected)] = value; setState(() {}); await store.saveMoods(moods); }
  Future<void> openTimer() async { final key = Habit.key(selected); final value = await Navigator.push<int>(context, MaterialPageRoute(builder: (_) => FocusTimer(initial: timers[key] ?? 0))); if (value == null) return; timers[key] = value; setState(() {}); await store.saveTimerSeconds(timers); }
  Future<void> setPin() async { final value = await showDialog<String>(context: context, builder: (_) => const PinDialog()); if (value == null) return; await store.savePin(value); setState(() { pin = value.isEmpty ? null : value; locked = false; }); }
  Future<void> unlock() async { final ok = await showDialog<bool>(context: context, barrierDismissible: false, builder: (_) => LockDialog(pin: pin!)); if (ok == true && mounted) setState(() => locked = false); }
  @override Widget build(BuildContext context) { if (loading) return const Scaffold(body: Center(child: CircularProgressIndicator())); if (locked) return LockScreen(onUnlock: unlock); final pages = <Widget>[Dashboard(habits: habits, date: selected, moods: moods, onToggle: toggleHabit, onEdit: editHabit, onOpen: openHabit, onAdd: addHabit, onMood: setMood, onTimer: openTimer), Daily(habits: habits, date: selected, onDate: (d) => setState(() => selected = d), onToggle: toggleHabit, onEdit: editHabit, onOpen: openHabit, onAdd: addHabit), Stats(habits: habits), TodoPage(todos: todos, onAdd: addTodo, onEdit: editTodo, onToggle: toggleTodo, onDelete: deleteTodo), Profile(habits: habits, hasPin: pin != null, onTimer: openTimer, onPin: setPin)]; return Scaffold(body: SafeArea(child: IndexedStack(index: tab, children: pages)), bottomNavigationBar: NavigationBar(selectedIndex: tab, indicatorColor: AppColors.soft, onDestinationSelected: (v) => setState(() => tab = v), destinations: const [NavigationDestination(icon: Icon(Icons.home_outlined), selectedIcon: Icon(Icons.home), label: 'Home'), NavigationDestination(icon: Icon(Icons.check_circle_outline), selectedIcon: Icon(Icons.check_circle), label: 'Habits'), NavigationDestination(icon: Icon(Icons.insights_outlined), selectedIcon: Icon(Icons.insights), label: 'Stats'), NavigationDestination(icon: Icon(Icons.list_alt_outlined), selectedIcon: Icon(Icons.list_alt), label: 'To-Do'), NavigationDestination(icon: Icon(Icons.person_outline), selectedIcon: Icon(Icons.person), label: 'Profile')])); }
}

