class _HabitEditorState extends State<HabitEditor> { late TextEditingController name, category, goal, unit, tags, notes; String frequency = 'Every day'; List<int> weekdays = [1,2,3,4,5,6,7]; bool pinned = false, active = true; @override void initState() { super.initState(); final h = widget.habit; name = TextEditingController(text: h?.name ?? ''); category = TextEditingController(text: h?.category ?? 'Daily'); goal = TextEditingController(text: '${h?.goal ?? 1}'); unit = TextEditingController(text: h?.unit ?? 'times'); tags = TextEditingController(text: h?.tags.join(', ') ?? ''); notes = TextEditingController(text: h?.notes ?? ''); frequency = h?.frequency ?? 'Every day'; weekdays = List<int>.from(h?.weekdays ?? weekdays); pinned = h?.pinned ?? false; active = h?.active ?? true; } @override void dispose() { name.dispose(); category.dispose(); goal.dispose(); unit.dispose(); tags.dispose(); notes.dispose(); super.dispose(); } void save() { final n = int.tryParse(goal.text) ?? 1; final tagList = tags.text.split(',').map((x) => x.trim()).where((x) => x.isNotEmpty).toList(); Navigator.pop(context, HabitForm(name: name.text, category: category.text, goal: n.clamp(1, 1000000).toInt(), unit: unit.text, frequency: frequency, weekdays: weekdays, tags: tagList, notes: notes.text, pinned: pinned, active: active)); } void remove() { Navigator.pop(context, HabitForm(name: name.text, category: category.text, goal: 1, unit: unit.text, frequency: frequency, weekdays: weekdays, tags: [], notes: '', pinned: false, active: false, delete: true)); } @override Widget build(BuildContext context) { final frequencyItems = <DropdownMenuItem<String>>[]; for (final x in ['Every day','Weekdays','Custom days']) frequencyItems.add(DropdownMenuItem<String>(value: x, child: Text(x))); final dayWidgets = <Widget>[]; if (frequency == 'Custom days') { final labels = ['M','T','W','T','F','S','S']; for (var i=0;i<7;i++) { final day=i+1; dayWidgets.add(FilterChip(label: Text(labels[i]), selected: weekdays.contains(day), onSelected: (v) => setState(() { if (v) { if (!weekdays.contains(day)) weekdays.add(day); } else { weekdays.remove(day); } }))); } } return Padding(padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom), child: SingleChildScrollView(padding: const EdgeInsets.all(20), child: Column(children: [Text(widget.habit == null ? 'New habit' : 'Edit habit', style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w900)), const SizedBox(height: 14), TextField(controller: name, decoration: const InputDecoration(labelText: 'Habit name')), const SizedBox(height: 10), TextField(controller: category, decoration: const InputDecoration(labelText: 'Category')), const SizedBox(height: 10), Row(children: [Expanded(child: TextField(controller: goal, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Goal'))), const SizedBox(width: 10), Expanded(child: TextField(controller: unit, decoration: const InputDecoration(labelText: 'Unit')))]), const SizedBox(height: 10), DropdownButtonFormField<String>(value: frequency, items: frequencyItems, onChanged: (x) => setState(() => frequency = x ?? 'Every day'), decoration: const InputDecoration(labelText: 'Frequency')), if (dayWidgets.isNotEmpty) Wrap(spacing: 4, children: dayWidgets), const SizedBox(height: 10), TextField(controller: tags, decoration: const InputDecoration(labelText: 'Tags, comma separated')), const SizedBox(height: 10), TextField(controller: notes, maxLines: 3, decoration: const InputDecoration(labelText: 'Notes')), SwitchListTile(value: pinned, onChanged: (v) => setState(() => pinned = v), title: const Text('Pin habit')), SwitchListTile(value: active, onChanged: (v) => setState(() => active = v), title: const Text('Active')), Row(children: [if (widget.habit != null) TextButton(onPressed: remove, child: const Text('Delete')), const Spacer(), FilledButton(onPressed: save, child: const Text('Save'))]) ]))); } }
